#[test]
fn iroh_daemon_proxy_frame_reader_charges_budget_before_body_read() {
    assert_eq!(
        crate::roaming::IROH_DAEMON_PROXY_CONNECTION_IDLE_TIMEOUT,
        Duration::from_secs(120)
    );
    assert_eq!(
        crate::roaming::IROH_DAEMON_PROXY_STREAM_IO_TIMEOUT,
        Duration::from_secs(30)
    );
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    runtime.block_on(async {
        use tokio::io::AsyncWriteExt;

        let budget = crate::roaming::IrohProxyByteBudget::new(8);
        let (mut writer, mut reader) = tokio::io::duplex(16);
        writer
            .write_all(&4_u32.to_be_bytes())
            .await
            .expect("write length");
        writer.write_all(&[1, 2, 3, 4]).await.expect("write body");

        let (frame, permit) =
            crate::roaming::read_iroh_proxy_frame_async(&mut reader, &budget, "test")
                .await
                .expect("read frame");
        assert_eq!(frame, [0, 0, 0, 4, 1, 2, 3, 4]);
        assert_eq!(budget.in_flight_bytes(), 8);
        drop(permit);
        assert_eq!(budget.in_flight_bytes(), 0);

        let budget = crate::roaming::IrohProxyByteBudget::new(16);
        let (mut writer, mut reader) = tokio::io::duplex(32);
        let mut extended_frame = crate::OBJECT_FRAME_EXTENDED_LENGTH_SENTINEL
            .to_be_bytes()
            .to_vec();
        extended_frame.extend_from_slice(&4_u64.to_be_bytes());
        extended_frame.extend_from_slice(&[1, 2, 3, 4]);
        writer
            .write_all(&extended_frame)
            .await
            .expect("write extended frame");

        let (frame, permit) =
            crate::roaming::read_iroh_proxy_frame_async(&mut reader, &budget, "test")
                .await
                .expect("read extended proxy frame");
        assert_eq!(frame, extended_frame);
        assert_eq!(budget.in_flight_bytes(), 16);
        drop(permit);
        assert_eq!(budget.in_flight_bytes(), 0);

        let budget = crate::roaming::IrohProxyByteBudget::new(7);
        let (mut writer, mut reader) = tokio::io::duplex(16);
        writer
            .write_all(&4_u32.to_be_bytes())
            .await
            .expect("write length only");
        let error = tokio::time::timeout(
            Duration::from_millis(100),
            crate::roaming::read_iroh_proxy_frame_async(&mut reader, &budget, "test"),
        )
        .await
        .expect("budget rejection should not wait for body")
        .expect_err("budget error");
        assert!(matches!(
            error,
            NetworkError::IrohProxyFrameBudgetExceeded {
                frame_bytes: 8,
                in_flight_bytes: 0,
                max_in_flight_bytes: 7,
            }
        ));
        assert_eq!(budget.in_flight_bytes(), 0);

        let budget = crate::roaming::IrohProxyByteBudget::new(16);
        let (mut writer, mut reader) = tokio::io::duplex(16);
        writer
            .write_all(&4_u32.to_be_bytes())
            .await
            .expect("write length");
        writer.write_all(&[1, 2]).await.expect("write partial body");
        drop(writer);
        let error = crate::roaming::read_iroh_proxy_frame_async(&mut reader, &budget, "test")
            .await
            .expect_err("partial body");
        assert_eq!(
            error,
            NetworkError::Io {
                operation: "read iroh daemon test frame body".to_string(),
                detail: "peer closed during object frame body: read 2 of 4 bytes".to_string(),
            }
        );
        assert_eq!(
            budget.in_flight_bytes(),
            0,
            "aborted frame reads must release the reserved proxy budget"
        );

        let budget = crate::roaming::IrohProxyByteBudget::new(16);
        let (mut writer, mut reader) = tokio::io::duplex(16);
        writer
            .write_all(&4_u32.to_be_bytes())
            .await
            .expect("write length for timeout");
        let error = crate::roaming::read_iroh_proxy_frame_async_with_idle_timeout(
            &mut reader,
            &budget,
            "test",
            Duration::from_millis(10),
        )
        .await
        .expect_err("slow body should time out");
        assert_eq!(
            error,
            NetworkError::Io {
                operation: "read iroh daemon test frame body".to_string(),
                detail: "timed out after 10ms without body read progress".to_string(),
            }
        );
        assert_eq!(
            budget.in_flight_bytes(),
            0,
            "timed-out frame reads must release the reserved proxy budget"
        );

        let budget = crate::roaming::IrohProxyByteBudget::new(16);
        let (mut writer, mut reader) = tokio::io::duplex(16);
        let writer_task = tokio::spawn(async move {
            writer
                .write_all(&4_u32.to_be_bytes())
                .await
                .expect("write length for slow body");
            for byte in [1_u8, 2, 3, 4] {
                tokio::time::sleep(Duration::from_millis(10)).await;
                writer.write_all(&[byte]).await.expect("write body byte");
            }
        });
        let (frame, permit) = crate::roaming::read_iroh_proxy_frame_async_with_idle_timeout(
            &mut reader,
            &budget,
            "test",
            Duration::from_millis(20),
        )
        .await
        .expect("body read should continue while bytes make progress");
        assert_eq!(frame, [0, 0, 0, 4, 1, 2, 3, 4]);
        assert_eq!(budget.in_flight_bytes(), 8);
        drop(permit);
        writer_task.await.expect("slow body writer");
        assert_eq!(budget.in_flight_bytes(), 0);

        let (mut writer, _reader) = tokio::io::duplex(1);
        let error = crate::roaming::write_iroh_proxy_frame_async_with_idle_timeout(
            &mut writer,
            &[7_u8; 1024],
            "test response",
            Duration::from_millis(10),
        )
        .await
        .expect_err("slow response consumer should time out");
        assert_eq!(
            error,
            NetworkError::Io {
                operation: "write iroh daemon proxy frame".to_string(),
                detail: "timed out after 10ms without test response write progress".to_string(),
            }
        );
    });
}

#[test]
fn connectivity_sort_uses_iroh_after_direct_tcp_is_known_unavailable() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-connectivity-sort");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_connectivity_sort").expect("cluster");
    let node_a = NodeId::from_legacy_named("node_connectivity_sort_a").expect("node a");
    let node_b = NodeId::from_legacy_named("node_connectivity_sort_b").expect("node b");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "connectivity sort",
        node_a.clone(),
        "node a",
        "pk-a",
        now,
    );
    let tcp = daemon_lan_endpoint(&node_b, "192.0.2.55:21353".to_string(), 20);
    let iroh = ClusterEndpointRecord {
        endpoint_id: stable_iroh_endpoint_id(&node_b, "iroh_public_key_sort"),
        node_id: node_b.clone(),
        transport: ClusterTransportKind::Iroh,
        address: "iroh://iroh_public_key_sort?relay=https://relay.example./".to_string(),
        source: ClusterEndpointSource::Rendezvous,
        privacy: ClusterEndpointPrivacy::Relayed,
        priority: 90,
        last_observed_latency_ms: None,
    };
    let mut member_b =
        ClusterMemberRecord::local_voter(cluster_id.clone(), node_b.clone(), "node b", "pk-b", now);
    member_b.capabilities = main_daemon_capabilities(&member_b.role);
    member_b.allowed_capabilities = member_b.capabilities.clone();
    member_b.endpoints = vec![tcp.clone(), iroh.clone()];
    state.members.push(member_b);
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");
    sync_cluster_connectivity_records_to_kv(
        &paths,
        &node_a,
        vec![
            cluster_connectivity_record(
                &state,
                &tcp,
                ClusterConnectivityState::Unreachable,
                None,
                3,
                None,
                Some("failed".to_string()),
                now,
                60,
            ),
            cluster_connectivity_record(
                &state,
                &iroh,
                ClusterConnectivityState::Healthy,
                Some(50),
                0,
                Some("ok".to_string()),
                None,
                now,
                60,
            ),
        ],
    )
    .expect("connectivity records");

    let targets = cluster_sync_targets_with_connectivity(&paths, &state);

    assert_eq!(
        targets.first().map(|endpoint| &endpoint.endpoint_id),
        Some(&iroh.endpoint_id)
    );
}

#[test]
fn connectivity_graph_keys_records_by_source_target_and_endpoint() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-connectivity-graph-key");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_connectivity_graph_key").expect("cluster");
    let node_a = NodeId::from_legacy_named("node_connectivity_graph_key_a").expect("node a");
    let node_b = NodeId::from_legacy_named("node_connectivity_graph_key_b").expect("node b");
    let node_c = NodeId::from_legacy_named("node_connectivity_graph_key_c").expect("node c");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "connectivity graph key",
        node_a.clone(),
        "node a",
        "pk-a",
        now,
    );
    let shared_endpoint_id =
        ClusterEndpointId::from_legacy_named("endpoint_connectivity_graph_key_shared")
            .expect("endpoint");
    let endpoint_b = ClusterEndpointRecord {
        endpoint_id: shared_endpoint_id.clone(),
        node_id: node_b.clone(),
        transport: ClusterTransportKind::LanTcp,
        address: "10.0.0.41:21353".to_string(),
        source: ClusterEndpointSource::Observed,
        privacy: ClusterEndpointPrivacy::Lan,
        priority: 1,
        last_observed_latency_ms: None,
    };
    let endpoint_c = ClusterEndpointRecord {
        endpoint_id: shared_endpoint_id,
        node_id: node_c.clone(),
        transport: ClusterTransportKind::LanTcp,
        address: "10.0.0.42:21353".to_string(),
        source: ClusterEndpointSource::Observed,
        privacy: ClusterEndpointPrivacy::Lan,
        priority: 20,
        last_observed_latency_ms: None,
    };
    for (node_id, endpoint, public_key) in [
        (node_b.clone(), endpoint_b.clone(), "pk-b"),
        (node_c.clone(), endpoint_c.clone(), "pk-c"),
    ] {
        let mut member =
            ClusterMemberRecord::local_voter(cluster_id.clone(), node_id, "node", public_key, now);
        member.capabilities = main_daemon_capabilities(&member.role);
        member.allowed_capabilities = member.capabilities.clone();
        member.endpoints = vec![endpoint];
        state.members.push(member);
    }
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");
    sync_cluster_connectivity_records_to_kv(
        &paths,
        &node_a,
        vec![cluster_connectivity_record(
            &state,
            &endpoint_b,
            ClusterConnectivityState::Unreachable,
            None,
            3,
            None,
            Some("failed".to_string()),
            now,
            60,
        )],
    )
    .expect("connectivity records");

    let targets = cluster_sync_targets_with_connectivity(&paths, &state);

    assert_eq!(
        targets.first().map(|endpoint| &endpoint.node_id),
        Some(&node_c)
    );
}

#[test]
fn connectivity_graph_indexes_equivalent_endpoint_addresses() {
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_connectivity_address_index").expect("cluster");
    let source = NodeId::from_legacy_named("node_connectivity_address_source").expect("source");
    let target = NodeId::from_legacy_named("node_connectivity_address_target").expect("target");
    let recorded_endpoint_id =
        ClusterEndpointId::from_legacy_named("endpoint_connectivity_address_recorded")
            .expect("endpoint");
    let query_endpoint_id =
        ClusterEndpointId::from_legacy_named("endpoint_connectivity_address_query")
            .expect("endpoint");
    let graph = ClusterConnectivityGraph::from_records(
        source.clone(),
        [ClusterConnectivityRecord {
            cluster_id: cluster_id.clone(),
            source_node_id: source.clone(),
            target_node_id: target.clone(),
            endpoint_id: recorded_endpoint_id.clone(),
            transport: ClusterTransportKind::LanTcp,
            address: "[2001:0db8:0:0:0:0:0:1]:21353".to_string(),
            state: ClusterConnectivityState::Unreachable,
            latency_ms: None,
            consecutive_failures: 3,
            last_success_at: None,
            last_failure_at: Some("failed".to_string()),
            observed_at: now,
            expires_at: now + time::Duration::seconds(30),
        }],
    );
    let endpoint = ClusterEndpointRecord {
        endpoint_id: query_endpoint_id,
        node_id: target,
        transport: ClusterTransportKind::LanTcp,
        address: "[2001:db8::1]:21353".to_string(),
        source: ClusterEndpointSource::Observed,
        privacy: ClusterEndpointPrivacy::Lan,
        priority: 0,
        last_observed_latency_ms: None,
    };

    let record = graph
        .record_for_endpoint(&endpoint)
        .expect("equivalent socket address lookup");
    assert_eq!(record.endpoint_id, recorded_endpoint_id);
    assert_eq!(graph.unavailability_rank(&endpoint), 1);
}

#[test]
fn connectivity_graph_indexes_best_healthy_endpoint_by_pair() {
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_connectivity_best_index").expect("cluster");
    let source = NodeId::from_legacy_named("node_connectivity_best_source").expect("source");
    let target = NodeId::from_legacy_named("node_connectivity_best_target").expect("target");
    let unrelated =
        NodeId::from_legacy_named("node_connectivity_best_unrelated").expect("unrelated");
    let slow_endpoint_id =
        ClusterEndpointId::from_legacy_named("endpoint_connectivity_best_slow").expect("endpoint");
    let fast_endpoint_id =
        ClusterEndpointId::from_legacy_named("endpoint_connectivity_best_fast").expect("endpoint");
    let unrelated_endpoint_id =
        ClusterEndpointId::from_legacy_named("endpoint_connectivity_best_unrelated")
            .expect("endpoint");
    let records = [
        ClusterConnectivityRecord {
            cluster_id: cluster_id.clone(),
            source_node_id: source.clone(),
            target_node_id: target.clone(),
            endpoint_id: slow_endpoint_id,
            transport: ClusterTransportKind::LanTcp,
            address: "10.0.0.80:21353".to_string(),
            state: ClusterConnectivityState::Healthy,
            latency_ms: Some(50),
            consecutive_failures: 0,
            last_success_at: Some("ok".to_string()),
            last_failure_at: None,
            observed_at: now,
            expires_at: now + time::Duration::seconds(30),
        },
        ClusterConnectivityRecord {
            cluster_id: cluster_id.clone(),
            source_node_id: source.clone(),
            target_node_id: target.clone(),
            endpoint_id: fast_endpoint_id.clone(),
            transport: ClusterTransportKind::Iroh,
            address: "iroh://fast".to_string(),
            state: ClusterConnectivityState::Healthy,
            latency_ms: Some(5),
            consecutive_failures: 0,
            last_success_at: Some("ok".to_string()),
            last_failure_at: None,
            observed_at: now,
            expires_at: now + time::Duration::seconds(30),
        },
        ClusterConnectivityRecord {
            cluster_id,
            source_node_id: source.clone(),
            target_node_id: unrelated,
            endpoint_id: unrelated_endpoint_id,
            transport: ClusterTransportKind::LanTcp,
            address: "10.0.0.81:21353".to_string(),
            state: ClusterConnectivityState::Healthy,
            latency_ms: Some(1),
            consecutive_failures: 0,
            last_success_at: Some("ok".to_string()),
            last_failure_at: None,
            observed_at: now,
            expires_at: now + time::Duration::seconds(30),
        },
    ];
    let graph = ClusterConnectivityGraph::from_records(source.clone(), records);

    let endpoint = graph
        .best_healthy_endpoint(&source, &target)
        .expect("best healthy endpoint");
    assert_eq!(endpoint.endpoint_id, fast_endpoint_id);
    assert_eq!(endpoint.address, "iroh://fast");
    assert_eq!(endpoint.last_observed_latency_ms, Some(5));
}

