#[test]
fn main_daemon_command_targets_skip_folded_shadow_daemon_endpoints() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-main-daemon-shadow-filter");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_network_main_daemon_shadow_filter").expect("cluster");
    let local =
        NodeId::from_legacy_named("node_network_main_daemon_shadow_filter_local").expect("local");
    let remote =
        NodeId::from_legacy_named("node_network_main_daemon_shadow_filter_remote").expect("remote");
    let shadow = shadow_daemon_node_id(&remote);
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "network main daemon shadow filter",
        local,
        "local",
        "pk-local",
        now,
    );
    let main_endpoint = daemon_lan_endpoint(&remote, "node2:21353".to_string(), 5);
    let mut folded_shadow_endpoint = daemon_lan_endpoint(&shadow, "node2:21354".to_string(), 5);
    folded_shadow_endpoint.node_id = remote.clone();
    let port_only_shadow_endpoint = daemon_lan_endpoint(&remote, "node2:21354".to_string(), 5);
    let mut member =
        ClusterMemberRecord::local_voter(cluster_id, remote, "remote", "pk-remote", now);
    member.capabilities = main_daemon_capabilities(&member.role);
    member.allowed_capabilities = member.capabilities.clone();
    member.endpoints = vec![
        folded_shadow_endpoint.clone(),
        port_only_shadow_endpoint.clone(),
        main_endpoint.clone(),
    ];
    state.members.push(member);
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");

    let selector = ClusterEndpointSelector::new(&paths, &state);
    let candidates = selector.select(ClusterEndpointSelectionPurpose::MainDaemonCommandCandidates);
    let relay_hop_candidates = selector.select(ClusterEndpointSelectionPurpose::RelayHop);
    let relay_hop_for_remote = selector.select_node(
        ClusterEndpointSelectionPurpose::RelayHop,
        &main_endpoint.node_id,
    );
    let dfs_targets = selector.select(ClusterEndpointSelectionPurpose::DfsData);
    assert_eq!(
        candidates
            .iter()
            .map(|endpoint| endpoint.endpoint_id.clone())
            .collect::<Vec<_>>(),
        vec![main_endpoint.endpoint_id.clone()],
        "main daemon command candidates must not include shadow supervision endpoints folded under the main member"
    );
    assert_eq!(
        relay_hop_candidates
            .iter()
            .map(|endpoint| endpoint.endpoint_id.clone())
            .collect::<Vec<_>>(),
        vec![main_endpoint.endpoint_id.clone()],
        "relay-hop endpoint selection must use the same main-daemon surface instead of a bespoke shadow-prone path"
    );
    assert_eq!(
        relay_hop_for_remote
            .iter()
            .map(|endpoint| endpoint.endpoint_id.clone())
            .collect::<Vec<_>>(),
        vec![main_endpoint.endpoint_id.clone()],
        "node-scoped relay-hop selection should return only the target main endpoint"
    );
    assert!(
        dfs_targets.iter().all(|endpoint| endpoint.endpoint_id
            != folded_shadow_endpoint.endpoint_id
            && endpoint.endpoint_id != port_only_shadow_endpoint.endpoint_id),
        "DFS data routing uses the same main-daemon target surface"
    );
    let remote_member = state
        .members
        .iter()
        .find(|member| member.node_id == main_endpoint.node_id)
        .expect("remote main member");
    let status_targets = selector.select_member(
        remote_member,
        ClusterEndpointSelectionPurpose::MemberDaemonStatus,
    );
    assert_eq!(
        status_targets
            .iter()
            .map(|endpoint| endpoint.endpoint_id.clone())
            .collect::<Vec<_>>(),
        vec![main_endpoint.endpoint_id],
        "main daemon status probes must keep trying main endpoints instead of accepting folded shadow endpoints"
    );
}

#[test]
fn main_daemon_command_targets_filter_known_unreachable_endpoints() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-main-daemon-targets-unreachable");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_network_main_daemon_unreachable").expect("cluster");
    let local =
        NodeId::from_legacy_named("node_network_main_daemon_unreachable_local").expect("local");
    let remote =
        NodeId::from_legacy_named("node_network_main_daemon_unreachable_remote").expect("remote");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "network main daemon unreachable",
        local,
        "local",
        "pk-local",
        now,
    );
    let stale_tcp = daemon_lan_endpoint(&remote, "10.0.0.41:21353".to_string(), 10);
    let mut member =
        ClusterMemberRecord::local_voter(cluster_id, remote, "remote", "pk-remote", now);
    member.capabilities = main_daemon_capabilities(&member.role);
    member.allowed_capabilities = member.capabilities.clone();
    member.endpoints = vec![stale_tcp.clone()];
    state.members.push(member);
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");
    sync_cluster_connectivity_records_to_kv(
        &paths,
        &state.local_node_id,
        vec![cluster_connectivity_record(
            &state,
            &stale_tcp,
            ClusterConnectivityState::Unreachable,
            None,
            CLUSTER_CONNECTIVITY_FAILURE_THRESHOLD,
            None,
            Some("identity mismatch".to_string()),
            now,
            60,
        )],
    )
    .expect("connectivity records");

    let targets = ClusterEndpointSelector::new(&paths, &state)
        .select(ClusterEndpointSelectionPurpose::MainDaemonCommand);

    assert!(
        targets.is_empty(),
        "known-unreachable direct endpoints should not remain daemon command targets"
    );
    let dfs_targets = ClusterEndpointSelector::new(&paths, &state)
        .select(ClusterEndpointSelectionPurpose::DfsData);
    assert_eq!(
        dfs_targets
            .iter()
            .map(|endpoint| &endpoint.endpoint_id)
            .collect::<Vec<_>>(),
        vec![&stale_tcp.endpoint_id],
        "DFS data routing should keep the target record so relay can handle known-bad direct paths"
    );
}

