#[test]
fn connectivity_full_sync_plans_bounded_batches() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-connectivity-bounded-planner");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_connectivity_bounded_planner").expect("cluster");
    let source_node =
        NodeId::from_legacy_named("node_connectivity_bounded_planner_source").expect("source");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "connectivity bounded planner",
        source_node.clone(),
        "source",
        "pk-source",
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");

    let mut store = InProcessKvStore::new();
    let mut stale_keys = Vec::new();
    for index in 0..5 {
        let target_node =
            NodeId::from_legacy_named(format!("node_connectivity_bounded_target_{index}"))
                .expect("target");
        let endpoint = daemon_lan_endpoint(&target_node, format!("10.52.0.{index}:21353"), 10);
        let record = cluster_connectivity_record(
            &state,
            &endpoint,
            ClusterConnectivityState::Healthy,
            Some(9),
            0,
            Some("stale".to_string()),
            None,
            now,
            600,
        );
        let key = cluster_connectivity_key(
            &record.source_node_id,
            &record.target_node_id,
            &record.endpoint_id,
        );
        store
            .put_serde(key.clone(), &record, None)
            .expect("seed stale connectivity");
        stale_keys.push(key);
    }
    write_cluster_kv_snapshot(&paths, &store.snapshot()).expect("write snapshot");

    let incoming_target =
        NodeId::from_legacy_named("node_connectivity_bounded_target_incoming").expect("target");
    let incoming_endpoint =
        daemon_lan_endpoint(&incoming_target, "10.52.0.99:21353".to_string(), 10);
    let incoming = cluster_connectivity_record(
        &state,
        &incoming_endpoint,
        ClusterConnectivityState::Healthy,
        Some(7),
        0,
        Some("current".to_string()),
        None,
        now,
        600,
    );
    let incoming_key = cluster_connectivity_key(
        &incoming.source_node_id,
        &incoming.target_node_id,
        &incoming.endpoint_id,
    );

    let first = cluster_connectivity_full_sync_batch_ops(
        &paths,
        &source_node,
        std::slice::from_ref(&incoming),
        3,
    )
    .expect("first batch");
    assert_eq!(first.len(), 3);
    assert!(first.iter().all(|op| matches!(op, KvOp::Delete { .. })));
    append_cluster_raft_command(
        &paths,
        &source_node,
        KvCommand::Txn(KvTxn {
            compares: Vec::new(),
            success: first,
            failure: Vec::new(),
        }),
    )
    .expect("append first batch");

    let second = cluster_connectivity_full_sync_batch_ops(
        &paths,
        &source_node,
        std::slice::from_ref(&incoming),
        3,
    )
    .expect("second batch");
    assert!(second.len() <= 3);
    assert_eq!(
        second
            .iter()
            .filter(|op| matches!(op, KvOp::Delete { .. }))
            .count(),
        2
    );
    assert!(
        second
            .iter()
            .any(|op| matches!(op, KvOp::Put { key, .. } if key == &incoming_key))
    );
    append_cluster_raft_command(
        &paths,
        &source_node,
        KvCommand::Txn(KvTxn {
            compares: Vec::new(),
            success: second,
            failure: Vec::new(),
        }),
    )
    .expect("append second batch");

    let final_ops = cluster_connectivity_full_sync_batch_ops(
        &paths,
        &source_node,
        std::slice::from_ref(&incoming),
        3,
    )
    .expect("final batch");
    assert!(final_ops.is_empty());

    let snapshot = read_cluster_kv_current_snapshot(&paths).expect("read snapshot");
    assert!(snapshot.get(&incoming_key).is_some());
    assert!(
        stale_keys
            .iter()
            .all(|key| snapshot.get(key.as_str()).is_none())
    );
}

#[derive(Default)]
struct RecordingClusterConnectivityPublishHost {
    cache_matches: bool,
    cache_checks: usize,
    remembers: usize,
    commits: Vec<usize>,
    last_txn: Option<KvTxn>,
}

impl ClusterConnectivityPublishHost for RecordingClusterConnectivityPublishHost {
    type Error = NetworkError;

    fn published_connectivity_record_set_matches(
        &mut self,
        _paths: &ClusterPaths,
        _source_node_id: &NodeId,
        _records: &[ClusterConnectivityRecord],
    ) -> bool {
        self.cache_checks += 1;
        self.cache_matches
    }

    fn remember_published_connectivity_record_set(
        &mut self,
        _paths: &ClusterPaths,
        _source_node_id: &NodeId,
        _records: &[ClusterConnectivityRecord],
    ) {
        self.remembers += 1;
    }

    fn commit_cluster_kv_txn_with_quorum(
        &mut self,
        paths: &ClusterPaths,
        state: &mut ClusterBootstrapState,
        txn: KvTxn,
    ) -> Result<KvSnapshot, Self::Error> {
        self.commits.push(txn.success.len());
        self.last_txn = Some(txn.clone());
        append_cluster_raft_command(paths, &state.local_node_id, KvCommand::Txn(txn))
    }
}

#[test]
fn connectivity_quorum_sync_driver_delegates_commits_and_remembers() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-connectivity-quorum-driver");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_connectivity_quorum_driver").expect("cluster");
    let source_node =
        NodeId::from_legacy_named("node_connectivity_quorum_driver_source").expect("source");
    let target_node =
        NodeId::from_legacy_named("node_connectivity_quorum_driver_target").expect("target");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "connectivity quorum driver",
        source_node.clone(),
        "source",
        "pk-source",
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state to kv");

    let endpoint = daemon_lan_endpoint(&target_node, "10.54.0.1:21353".to_string(), 10);
    let record = cluster_connectivity_record(
        &state,
        &endpoint,
        ClusterConnectivityState::Healthy,
        Some(6),
        0,
        Some("ok".to_string()),
        None,
        now,
        600,
    );
    let key = cluster_connectivity_key(
        &record.source_node_id,
        &record.target_node_id,
        &record.endpoint_id,
    );

    let mut host = RecordingClusterConnectivityPublishHost::default();
    let result = sync_cluster_connectivity_records_to_quorum_with_host(
        &paths,
        &source_node,
        vec![record.clone()],
        &mut host,
    )
    .expect("connectivity quorum sync");

    assert!(
        result.is_some(),
        "driver should return the committed snapshot"
    );
    assert_eq!(host.cache_checks, 1);
    assert_eq!(host.commits, vec![1]);
    assert_eq!(host.remembers, 1);
    assert!(
        host.last_txn
            .as_ref()
            .expect("committed txn")
            .success
            .iter()
            .any(|op| matches!(op, KvOp::Put { key: put_key, .. } if put_key == &key)),
        "network driver should plan connectivity publication"
    );
    assert_eq!(
        read_local_cluster_connectivity_records(&paths).expect("local records"),
        vec![record.clone()]
    );
    assert!(
        read_cluster_kv_current_snapshot(&paths)
            .expect("snapshot")
            .get(&key)
            .is_some(),
        "host-applied commit should publish connectivity into cluster KV"
    );

    host.cache_matches = true;
    host.commits.clear();
    let cached = sync_cluster_connectivity_records_to_quorum_with_host(
        &paths,
        &source_node,
        vec![record],
        &mut host,
    )
    .expect("cached connectivity quorum sync");
    assert!(cached.is_none(), "host cache hit should skip KV planning");
    assert_eq!(host.commits, Vec::<usize>::new());
    assert_eq!(host.remembers, 1, "cache-hit path should not re-remember");
}

/// Simulates a forwarding learner: commits land in the "voter's" in-memory
/// store and the response snapshot reflects them, but the local paths-backed
/// KV never advances (no fan-out, no import). The async sync loop must
/// terminate against the response snapshot instead of spinning on the stale
/// local view (the cold-formation maintenance-loop wedge).
struct ForwardingOnlyConnectivityPublishAsyncHost {
    voter_store: InProcessKvStore,
    commits: usize,
    apply_commits: bool,
}

impl ClusterConnectivityPublishAsyncHost for ForwardingOnlyConnectivityPublishAsyncHost {
    type Error = NetworkError;

    fn commit_cluster_kv_txn_with_quorum_async<'a>(
        &'a mut self,
        _paths: &'a ClusterPaths,
        _state: &'a mut ClusterBootstrapState,
        txn: KvTxn,
    ) -> ClusterMembershipRpcFuture<'a, KvSnapshot> {
        Box::pin(async move {
            self.commits += 1;
            if self.commits > 8 {
                return Err(NetworkError::Io {
                    operation: "test connectivity commit".to_string(),
                    detail: "connectivity sync loop did not converge".to_string(),
                });
            }
            if self.apply_commits {
                self.voter_store.txn(txn).map_err(NetworkError::from)?;
            }
            Ok(self.voter_store.snapshot())
        })
    }
}

#[test]
fn async_connectivity_quorum_sync_terminates_when_local_kv_lags_forwarded_commits() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-connectivity-forward-lag");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_connectivity_forward_lag").expect("cluster");
    let source_node =
        NodeId::from_legacy_named("node_connectivity_forward_lag_source").expect("source");
    let target_node =
        NodeId::from_legacy_named("node_connectivity_forward_lag_target").expect("target");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "connectivity forward lag",
        source_node.clone(),
        "source",
        "pk-source",
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state to kv");

    let endpoint = daemon_lan_endpoint(&target_node, "10.55.0.1:21353".to_string(), 10);
    let record = cluster_connectivity_record(
        &state,
        &endpoint,
        ClusterConnectivityState::Healthy,
        Some(6),
        0,
        Some("ok".to_string()),
        None,
        now,
        600,
    );
    let key = cluster_connectivity_key(
        &record.source_node_id,
        &record.target_node_id,
        &record.endpoint_id,
    );

    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");

    // Forwarded commits succeed at the voter; the local store stays stale.
    // The loop must converge from the response snapshot after one commit.
    let mut host = ForwardingOnlyConnectivityPublishAsyncHost {
        voter_store: InProcessKvStore::new(),
        commits: 0,
        apply_commits: true,
    };
    let result = runtime
        .block_on(sync_cluster_connectivity_records_to_quorum_async_with_host(
            runtime.handle(),
            &paths,
            &source_node,
            vec![record.clone()],
            &mut host,
        ))
        .expect("forward-lagged connectivity sync should converge");
    assert_eq!(
        host.commits, 1,
        "one commit should converge the loop via the response snapshot"
    );
    let snapshot = result.expect("committed snapshot");
    assert!(
        snapshot.get(&key).is_some(),
        "response snapshot should hold the published record"
    );

    // A stale response snapshot can still be returned after the commit was accepted
    // by the quorum path. The publisher should stop retrying the identical batch and
    // let the next maintenance cycle refresh from KV instead of wedging the tick.
    let mut stale_host = ForwardingOnlyConnectivityPublishAsyncHost {
        voter_store: InProcessKvStore::new(),
        commits: 0,
        apply_commits: false,
    };
    let stale_result = runtime
        .block_on(sync_cluster_connectivity_records_to_quorum_async_with_host(
            runtime.handle(),
            &paths,
            &source_node,
            vec![record],
            &mut stale_host,
        ))
        .expect("stale response snapshot should not wedge connectivity sync");
    assert_eq!(
        stale_host.commits, 1,
        "stale response progress must be detected on the iteration after the first commit"
    );
    assert!(stale_result.is_some());
}

#[test]
fn connectivity_full_sync_batches_large_stale_deletions() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-connectivity-large-delete");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_connectivity_large_delete").expect("cluster");
    let source_node =
        NodeId::from_legacy_named("node_connectivity_large_delete_source").expect("source");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "connectivity large delete",
        source_node.clone(),
        "source",
        "pk-source",
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");

    let mut store = InProcessKvStore::new();
    for index in 0..=sinomo_kv::MAX_KV_MUTATION_EVENTS_PER_COMMAND {
        let target_node =
            NodeId::from_legacy_named(format!("node_connectivity_large_delete_target_{index}"))
                .expect("target");
        let endpoint_id = ClusterEndpointId::from_legacy_named(format!(
            "endpoint_connectivity_large_delete_{index}"
        ))
        .expect("endpoint");
        let record = ClusterConnectivityRecord {
            cluster_id: cluster_id.clone(),
            source_node_id: source_node.clone(),
            target_node_id: target_node,
            endpoint_id: endpoint_id.clone(),
            transport: ClusterTransportKind::LanTcp,
            address: format!("10.43.{}.{}:21353", index / 256, index % 256),
            state: ClusterConnectivityState::Healthy,
            latency_ms: Some(9),
            consecutive_failures: 0,
            last_success_at: Some("stale".to_string()),
            last_failure_at: None,
            observed_at: now,
            expires_at: now + time::Duration::seconds(600),
        };
        match KvOp::put_serde(
            cluster_connectivity_key(&source_node, &record.target_node_id, &endpoint_id),
            &record,
            None,
        )
        .expect("connectivity put op")
        {
            KvOp::Put {
                key,
                value,
                lease_id,
            } => {
                store.put(key, value, lease_id).expect("seed connectivity");
            }
            _ => unreachable!("put_serde creates put op"),
        }
    }
    write_cluster_kv_snapshot(&paths, &store.snapshot()).expect("write large snapshot");

    sync_cluster_connectivity_records_to_kv(&paths, &source_node, Vec::new())
        .expect("batch stale connectivity deletes");
    let snapshot = read_cluster_kv_current_snapshot(&paths).expect("read current snapshot");
    assert!(
        snapshot
            .prefix_entries(&cluster_connectivity_source_prefix(&source_node))
            .next()
            .is_none(),
        "full sync should delete stale source records in bounded batches"
    );
}

#[test]
fn connectivity_sync_refreshes_stable_records_near_expiry() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-connectivity-refresh");
    let data_dir = sinomo_local::SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_network_connectivity_refresh").expect("cluster");
    let source_node_id =
        NodeId::from_legacy_named("node_network_connectivity_refresh_source").expect("source");
    let target_node_id =
        NodeId::from_legacy_named("node_network_connectivity_refresh_target").expect("target");
    let endpoint_id = ClusterEndpointId::from_legacy_named("endpoint_network_connectivity_refresh")
        .expect("endpoint");
    let mut stored = ClusterConnectivityRecord {
        cluster_id,
        source_node_id: source_node_id.clone(),
        target_node_id,
        endpoint_id,
        transport: ClusterTransportKind::LanTcp,
        address: "192.0.2.12:21353".to_string(),
        state: ClusterConnectivityState::Healthy,
        latency_ms: Some(12),
        consecutive_failures: 0,
        last_success_at: Some("2026-05-06T00:00:00Z".to_string()),
        last_failure_at: None,
        observed_at: now - time::Duration::seconds(300),
        expires_at: now + time::Duration::seconds(30),
    };
    let mut incoming = stored.clone();
    incoming.latency_ms = Some(18);
    incoming.observed_at = now;
    incoming.expires_at = now + time::Duration::seconds(900);

    let mut store = InProcessKvStore::new();
    store
        .put_serde(
            cluster_connectivity_key(
                &stored.source_node_id,
                &stored.target_node_id,
                &stored.endpoint_id,
            ),
            &stored,
            None,
        )
        .expect("stored connectivity");
    write_cluster_kv_snapshot(&paths, &store.snapshot()).expect("cluster kv snapshot");

    let ops = cluster_connectivity_sync_ops(&paths, &source_node_id, &[incoming.clone()])
        .expect("connectivity sync ops");
    assert_eq!(
        ops.len(),
        1,
        "stable connectivity records near expiry must refresh their KV TTL"
    );

    stored.expires_at = now + time::Duration::seconds(300);
    store
        .put_serde(
            cluster_connectivity_key(
                &stored.source_node_id,
                &stored.target_node_id,
                &stored.endpoint_id,
            ),
            &stored,
            None,
        )
        .expect("fresh stored connectivity");
    write_cluster_kv_snapshot(&paths, &store.snapshot()).expect("fresh cluster kv snapshot");
    let ops =
        cluster_connectivity_sync_ops(&paths, &source_node_id, &[incoming]).expect("fresh ops");
    assert!(
        ops.is_empty(),
        "fresh stable connectivity records should not be rewritten just to update timestamps"
    );
}

