#[test]
fn mdns_discovery_cache_returns_lan_quic_candidates_and_expires_records() {
    let cluster_id = ClusterId::from_legacy_named("cluster_home").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_desktop").expect("node");
    let mut cache = MdnsDiscoveryCache::new();
    cache.upsert(MdnsDiscoveryRecord::lan_quic(
        cluster_id.clone(),
        node_id.clone(),
        "192.168.1.20:21355",
        10,
        5,
    ));

    let candidates = cache.endpoint_candidates_for_node(&node_id);

    assert_eq!(cache.endpoints_for_cluster(&cluster_id).len(), 1);
    assert_eq!(candidates.len(), 1);
    assert_eq!(
        candidates[0].endpoint.transport,
        ClusterTransportKind::LanQuic
    );
    assert_eq!(cache.expire_after_tick(14), 0);
    assert_eq!(cache.expire_after_tick(15), 1);
    assert!(cache.endpoint_candidates_for_node(&node_id).is_empty());
    assert!(cache.endpoints_for_cluster(&cluster_id).is_empty());
    assert_eq!(cache.index_record_counts_for_test(), (0, 0));
}

#[test]
fn mdns_discovery_cache_reindexes_replaced_records() {
    let cluster_id = ClusterId::from_legacy_named("cluster_mdns_replace").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_mdns_replace").expect("node");
    let mut cache = MdnsDiscoveryCache::new();
    cache.upsert(MdnsDiscoveryRecord::lan_quic(
        cluster_id.clone(),
        node_id.clone(),
        "192.168.55.20:21355",
        10,
        5,
    ));
    cache.upsert(MdnsDiscoveryRecord::lan_quic(
        cluster_id.clone(),
        node_id.clone(),
        "192.168.55.20:21355",
        100,
        5,
    ));

    assert_eq!(
        cache.expire_after_tick(15),
        0,
        "a refreshed mDNS record must not be expired by its previous deadline index"
    );
    assert_eq!(cache.endpoint_candidates_for_node(&node_id).len(), 1);
    assert_eq!(cache.endpoints_for_cluster(&cluster_id).len(), 1);
    assert_eq!(cache.index_record_counts_for_test(), (1, 1));
    assert_eq!(cache.expire_after_tick(105), 1);
    assert!(cache.endpoint_candidates_for_node(&node_id).is_empty());
    assert!(cache.endpoints_for_cluster(&cluster_id).is_empty());
    assert_eq!(cache.index_record_counts_for_test(), (0, 0));
}

#[test]
fn mdns_discovery_records_clamp_advertised_ttl() {
    let cluster_id = ClusterId::from_legacy_named("cluster_mdns_ttl").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_mdns_ttl").expect("node");
    let endpoint = MdnsDiscoveryRecord::lan_quic(
        cluster_id.clone(),
        node_id.clone(),
        "192.168.51.20:21355",
        10,
        u64::MAX,
    )
    .endpoint;
    let advertisement = MdnsDiscoveryAdvertisement {
        ttl_ticks: u64::MAX,
        ..MdnsDiscoveryAdvertisement::new(cluster_id.clone(), node_id.clone(), vec![endpoint], 10)
    };
    let records = advertisement.records();

    assert_eq!(records.len(), 1);
    assert_eq!(
        records[0].expires_after_tick,
        10 + crate::lan::MAX_SINOMO_LAN_DISCOVERY_TTL_TICKS,
        "untrusted LAN advertisements must not pin stale roaming endpoints indefinitely"
    );

    let helper_record =
        MdnsDiscoveryRecord::lan_quic(cluster_id, node_id, "192.168.51.21:21355", 20, u64::MAX);
    assert_eq!(
        helper_record.expires_after_tick,
        20 + crate::lan::MAX_SINOMO_LAN_DISCOVERY_TTL_TICKS,
        "direct record helpers should share the same TTL bound"
    );
}

