#[test]
fn routes_session_events_to_participants() {
    let session_id = SessionId::from_legacy_named("sess_demo").expect("session");
    let mut registry = PeerRegistry::new();
    registry.register_node(node("node_mobile"));
    registry.register_node(node("node_desktop"));
    registry
        .join_session(
            session_id.clone(),
            NodeId::from_legacy_named("node_mobile").expect("node"),
        )
        .expect("join mobile");
    registry
        .join_session(
            session_id.clone(),
            NodeId::from_legacy_named("node_desktop").expect("node"),
        )
        .expect("join desktop");

    let event = EventEnvelope::new(
        EventId::from_legacy_named("evt_route").expect("event"),
        time::OffsetDateTime::now_utc(),
        NodeId::from_legacy_named("node_mobile").expect("node"),
        Source::new("test.route").expect("source"),
        EventKind::new("workflow.job.scoped").expect("kind"),
        Salience::new(0.8).expect("salience"),
        Confidence::new(1.0).expect("confidence"),
        RoutingMetadata::new(
            RoutingScope::Session,
            LatencyClass::Background,
            PrivacyClass::Derived,
        ),
    )
    .with_session(session_id);

    let mut store = InMemoryEventStore::new();
    let receipt = store.append(event).expect("append");
    let stored = store
        .replay(ReplayQuery::all().after(EventSequence(receipt.sequence.0 - 1)))
        .expect("replay")
        .pop()
        .expect("stored event");

    let mut router = InProcessRouter::new(registry);
    let deliveries = router.route_event(&stored).expect("route");
    assert_eq!(deliveries.len(), 2);
}

#[test]
fn peer_registry_routable_indexes_track_session_and_status_changes() {
    let node_a = NodeId::from_legacy_named("node_route_index_a").expect("node a");
    let node_b = NodeId::from_legacy_named("node_route_index_b").expect("node b");
    let session_id = SessionId::from_legacy_named("sess_route_index").expect("session");
    let mut registry = PeerRegistry::new();
    registry.register_node(node("node_route_index_a"));
    registry.register_node(node("node_route_index_b"));
    registry
        .join_session(session_id.clone(), node_a.clone())
        .expect("join a");
    registry
        .join_session(session_id.clone(), node_b.clone())
        .expect("join b");

    let expected_all = [node_a.clone(), node_b.clone()]
        .into_iter()
        .collect::<std::collections::BTreeSet<_>>();
    assert_eq!(
        registry
            .routable_session_nodes(&session_id)
            .into_iter()
            .collect::<std::collections::BTreeSet<_>>(),
        expected_all
    );
    assert_eq!(
        registry
            .routable_network_nodes()
            .into_iter()
            .collect::<std::collections::BTreeSet<_>>(),
        [node_a.clone(), node_b.clone()]
            .into_iter()
            .collect::<std::collections::BTreeSet<_>>()
    );

    registry
        .record_missed_heartbeat(&node_b, HeartbeatPolicy::default())
        .expect("first miss");
    assert_eq!(
        registry
            .routable_session_nodes(&session_id)
            .into_iter()
            .collect::<std::collections::BTreeSet<_>>(),
        [node_a.clone(), node_b.clone()]
            .into_iter()
            .collect::<std::collections::BTreeSet<_>>(),
        "degraded peers remain routable"
    );
    registry
        .record_missed_heartbeat(&node_b, HeartbeatPolicy::default())
        .expect("second miss");
    assert_eq!(
        registry.routable_session_nodes(&session_id),
        vec![node_a.clone()],
        "suspect peers should leave the maintained routable session index"
    );
    assert_eq!(registry.routable_network_nodes(), vec![node_a.clone()]);

    registry
        .record_heartbeat(&node_b, 42)
        .expect("heartbeat recovery");
    assert_eq!(
        registry
            .routable_session_nodes(&session_id)
            .into_iter()
            .collect::<std::collections::BTreeSet<_>>(),
        [node_a, node_b.clone()]
            .into_iter()
            .collect::<std::collections::BTreeSet<_>>()
    );
    assert!(
        registry.routable_network_nodes().contains(&node_b),
        "heartbeat recovery should restore the maintained routable network index"
    );
}

#[test]
fn in_process_transport_delivers_typed_frames() {
    let node_a = NodeId::from_legacy_named("node_a").expect("node");
    let node_b = NodeId::from_legacy_named("node_b").expect("node");
    let network = InProcessNetwork::new();
    let mut transport_a = network.add_node(node_a.clone());
    let mut transport_b = network.add_node(node_b.clone());
    let event = fixture_event("evt_transport", node_a.clone());

    let frame = NetworkFrame {
        frame_id: NetworkFrameId(1),
        source_node_id: node_a.clone(),
        target_node_id: node_b.clone(),
        message: MeshMessage {
            message_id: MeshMessageId(1),
            origin_node_id: node_a,
            target_node_id: node_b.clone(),
            body: MeshMessageBody::Event {
                delivery_id: RouteDeliveryId(1),
                event: Box::new(event.clone()),
            },
        },
    };

    transport_a
        .send(&node_b, frame.clone())
        .expect("send frame");
    let inbound = transport_b.drain_incoming().expect("drain");

    assert_eq!(inbound.len(), 1);
    assert_eq!(inbound[0].received_by, node_b);
    assert_eq!(inbound[0].frame, frame);
}

#[test]
fn in_process_transport_delivers_object_rpc_requests_without_frames() {
    let node_a = NodeId::from_legacy_named("node_object_rpc_a").expect("node");
    let node_b = NodeId::from_legacy_named("node_object_rpc_b").expect("node");
    let network = InProcessNetwork::new();
    let mut transport_a = network.add_node(node_a.clone());
    let mut transport_b = network.add_node(node_b.clone());
    let request = ObjectRpcRequest::encode_body("/test/object-message", "test.object", &42_u64)
        .expect("request");

    transport_a
        .send_object_rpc_request(&node_b, request.clone())
        .expect("send object rpc request");

    assert_eq!(
        transport_b.pending_incoming_count().expect("frame count"),
        Some(0),
        "object-RPC delivery must not populate the legacy frame mailbox"
    );
    assert!(
        transport_b
            .wait_for_incoming_object_rpc_request(Duration::ZERO)
            .expect("wait for object rpc request")
    );
    let inbound = transport_b
        .drain_incoming_object_rpc_requests()
        .expect("drain object rpc requests");

    assert_eq!(inbound.len(), 1);
    assert_eq!(inbound[0].received_by, node_b);
    assert_eq!(inbound[0].message.source_node_id, node_a);
    assert_eq!(inbound[0].message.target_node_id, node_b);
    assert_eq!(inbound[0].message.request, request);
    assert!(
        transport_b
            .drain_incoming()
            .expect("drain frames after object rpc")
            .is_empty()
    );
}

#[test]
fn in_process_transport_wait_for_incoming_wakes_on_send() {
    let node_a = NodeId::from_legacy_named("node_wait_sender").expect("node");
    let node_b = NodeId::from_legacy_named("node_wait_receiver").expect("node");
    let network = InProcessNetwork::new();
    let mut transport_a = network.add_node(node_a.clone());
    let mut transport_b = network.add_node(node_b.clone());
    let waiter_transport = transport_b.clone();
    let (ready_tx, ready_rx) = std::sync::mpsc::channel();
    let waiter = thread::spawn(move || {
        ready_tx.send(()).expect("signal waiter ready");
        let started = Instant::now();
        let woke = waiter_transport
            .wait_for_incoming(Duration::from_secs(5))
            .expect("wait for inbound frame");
        (started.elapsed(), woke)
    });
    ready_rx.recv().expect("waiter ready");
    thread::sleep(Duration::from_millis(50));

    transport_a
        .send(
            &node_b,
            NetworkFrame {
                frame_id: NetworkFrameId(1),
                source_node_id: node_a.clone(),
                target_node_id: node_b.clone(),
                message: MeshMessage {
                    message_id: MeshMessageId(1),
                    origin_node_id: node_a,
                    target_node_id: node_b.clone(),
                    body: MeshMessageBody::Heartbeat(Heartbeat {
                        node_id: node_b.clone(),
                        tick: 1,
                    }),
                },
            },
        )
        .expect("send frame");

    let (elapsed, woke) = waiter.join().expect("waiter thread");
    assert!(woke, "waiter should report queued inbound work");
    assert!(
        elapsed < Duration::from_secs(2),
        "waiter should wake on send instead of sleeping until timeout after {elapsed:?}"
    );
    assert_eq!(
        transport_b
            .drain_incoming()
            .expect("drain after wake")
            .len(),
        1
    );
}

