#[test]
fn delivery_ledger_outbound_wake_hint_tracks_immediate_and_waiting_work() {
    let node_a = NodeId::from_legacy_named("node_retry_wake_source").expect("node");
    let node_b = NodeId::from_legacy_named("node_retry_wake_target").expect("node");
    let mut ledger = DeliveryLedger::with_capacity(RetryPolicy::default(), 2);
    let event = fixture_event("evt_retry_wake", node_a);
    let delivery = RouteDelivery {
        delivery_id: RouteDeliveryId(1),
        event_sequence: EventSequence(1),
        event_id: event.event_id.clone(),
        target_node_id: node_b,
        latency_class: LatencyClass::Interactive,
        status: DeliveryStatus::Queued,
    };
    let now = Instant::now();

    assert_eq!(ledger.next_outbound_wake_at_at(now), None);
    ledger.enqueue(delivery, event).expect("enqueue");
    assert_eq!(ledger.next_outbound_wake_at_at(now), Some(now));
    ledger
        .mark_waiting_for_peer(RouteDeliveryId(1))
        .expect("waiting");
    assert_eq!(
        ledger.next_outbound_wake_at_at(now),
        None,
        "offline peer work should not create an idle retry wakeup"
    );
    ledger.mark_for_retry(RouteDeliveryId(1)).expect("retry");
    assert_eq!(
        ledger.next_outbound_wake_at_at(now),
        Some(now),
        "deadline-free retries should wake immediately"
    );
}

#[test]
fn delivery_ledger_sent_ack_deadline_retries_stale_in_flight_work() {
    let node_a = NodeId::from_legacy_named("node_ack_timeout_source").expect("node");
    let node_b = NodeId::from_legacy_named("node_ack_timeout_target").expect("node");
    let mut ledger = DeliveryLedger::with_capacity(RetryPolicy::default(), 2);
    let event = fixture_event("evt_ack_timeout_retry", node_a);
    let delivery = RouteDelivery {
        delivery_id: RouteDeliveryId(1),
        event_sequence: EventSequence(1),
        event_id: event.event_id.clone(),
        target_node_id: node_b,
        latency_class: LatencyClass::Interactive,
        status: DeliveryStatus::Queued,
    };
    let now = Instant::now();
    let deadline = now + crate::peer::ack_timeout_for_latency_class(&LatencyClass::Interactive);

    ledger.enqueue(delivery, event).expect("enqueue");
    ledger
        .mark_sent_at(RouteDeliveryId(1), now)
        .expect("mark sent");
    assert_eq!(
        ledger.next_outbound_wake_at_at(now),
        Some(deadline),
        "sent work should expose its ack deadline so schedulers can sleep until useful work exists"
    );
    assert_eq!(
        ledger.expire_ack_deadlines_at(deadline - Duration::from_millis(1)),
        0,
        "unexpired sent work must not become retryable early"
    );
    assert_eq!(
        ledger
            .record(&RouteDeliveryId(1))
            .expect("record")
            .delivery
            .status,
        DeliveryStatus::Sent
    );

    assert_eq!(ledger.expire_ack_deadlines_at(deadline), 1);
    let record = ledger.record(&RouteDeliveryId(1)).expect("record");
    assert_eq!(record.delivery.status, DeliveryStatus::Retrying);
    assert_eq!(record.attempts, 1);
    assert!(
        ledger.ready_delivery_ids_at(deadline).is_empty(),
        "ack timeouts should still respect retry backoff before resending"
    );
    let retry_wake = ledger
        .next_outbound_wake_at_at(deadline)
        .expect("retry wake");
    assert!(retry_wake > deadline);
    assert_eq!(
        ledger.ready_delivery_ids_at(retry_wake),
        vec![RouteDeliveryId(1)]
    );
}

#[test]
fn delivery_ledger_ack_deadline_expiry_uses_deadline_order() {
    let node_a = NodeId::from_legacy_named("node_ack_deadline_order_source").expect("node");
    let node_b = NodeId::from_legacy_named("node_ack_deadline_order_target").expect("node");
    let mut ledger = DeliveryLedger::with_capacity(RetryPolicy::default(), 2);
    let start = Instant::now();
    let ack_timeout = crate::peer::ack_timeout_for_latency_class(&LatencyClass::Interactive);
    for delivery_id in [RouteDeliveryId(1), RouteDeliveryId(2)] {
        let event = fixture_event(
            &format!("evt_ack_deadline_order_{}", delivery_id.0),
            node_a.clone(),
        );
        let delivery = RouteDelivery {
            delivery_id,
            event_sequence: EventSequence(delivery_id.0),
            event_id: event.event_id.clone(),
            target_node_id: node_b.clone(),
            latency_class: LatencyClass::Interactive,
            status: DeliveryStatus::Queued,
        };
        ledger.enqueue(delivery, event).expect("enqueue");
    }

    ledger
        .mark_sent_at(RouteDeliveryId(1), start + Duration::from_millis(500))
        .expect("mark later deadline");
    ledger
        .mark_sent_at(RouteDeliveryId(2), start)
        .expect("mark earlier deadline");

    assert_eq!(
        ledger.next_outbound_wake_at_at(start),
        Some(start + ack_timeout),
        "wake hints should use the earliest ack deadline, not delivery-id order"
    );
    assert_eq!(ledger.expire_ack_deadlines_at(start + ack_timeout), 1);
    assert_eq!(
        ledger
            .record(&RouteDeliveryId(2))
            .expect("earlier deadline record")
            .delivery
            .status,
        DeliveryStatus::Retrying
    );
    assert_eq!(
        ledger
            .record(&RouteDeliveryId(1))
            .expect("later deadline record")
            .delivery
            .status,
        DeliveryStatus::Sent
    );
}

#[test]
fn delivery_ledger_reconciles_sent_records_missing_ack_deadlines() {
    let node_a = NodeId::from_legacy_named("node_orphan_ack_deadline_source").expect("node");
    let node_b = NodeId::from_legacy_named("node_orphan_ack_deadline_target").expect("node");
    let mut ledger = DeliveryLedger::with_capacity(RetryPolicy::default(), 2);
    let event = fixture_event("evt_orphan_ack_deadline", node_a);
    let delivery = RouteDelivery {
        delivery_id: RouteDeliveryId(1),
        event_sequence: EventSequence(1),
        event_id: event.event_id.clone(),
        target_node_id: node_b,
        latency_class: LatencyClass::Interactive,
        status: DeliveryStatus::Queued,
    };
    let now = Instant::now();

    ledger.enqueue(delivery, event).expect("enqueue");
    ledger
        .mark_sent_at(RouteDeliveryId(1), now)
        .expect("mark sent");
    ledger.clear_ack_deadline_for_test(RouteDeliveryId(1));

    assert_eq!(
        ledger.next_outbound_wake_at_at(now),
        Some(now),
        "orphaned sent state should request reconciliation instead of sleeping forever"
    );
    assert_eq!(
        ledger.expire_ack_deadlines_at(now),
        1,
        "orphaned sent state should be handled as an ack timeout"
    );
    let record = ledger.record(&RouteDeliveryId(1)).expect("record");
    assert_eq!(record.delivery.status, DeliveryStatus::Retrying);
    assert_eq!(record.attempts, 1);
    assert!(
        ledger.ready_delivery_ids_at(now).is_empty(),
        "reconciled work should use normal retry backoff rather than spin immediately"
    );
    assert!(
        ledger.next_outbound_wake_at_at(now).expect("retry wake") > now,
        "scheduler should sleep until the retry backoff expires"
    );
}

#[test]
