#[tokio::test]
async fn missed_heartbeat_parks_sent_delivery_until_recovery() {
    let node_a = NodeId::from_legacy_named("node_sent_recovery_a").expect("node");
    let node_b = NodeId::from_legacy_named("node_sent_recovery_b").expect("node");
    let network = AsyncInProcessNetwork::new();
    let transport_a = network.add_node(node_a.clone());
    let transport_b = network.add_node(node_b.clone());
    let mut registry = PeerRegistry::new();
    registry.register_node(node("node_sent_recovery_a"));
    registry.register_node(node("node_sent_recovery_b"));
    let mut store = InMemoryEventStore::new();
    let event = fixture_event("evt_sent_recovery", node_a.clone()).with_target_node(node_b.clone());
    let receipt = store.append(event).expect("append");
    let stored = store
        .replay(ReplayQuery::all().after(EventSequence(receipt.sequence.0 - 1)))
        .expect("replay")
        .pop()
        .expect("stored");
    let service_a = NetworkService::new(registry.clone(), transport_a)
        .spawn_on_runtime(tokio::runtime::Handle::current(), store);
    let service_b = NetworkService::new(registry, transport_b)
        .spawn_on_runtime(tokio::runtime::Handle::current(), InMemoryEventStore::new());
    let delivery_id = service_a.enqueue_event(stored).await.expect("enqueue")[0].delivery_id;

    assert_eq!(service_a.pump_outbound().await.expect("send"), 1);
    assert_eq!(
        async_delivery_status(&service_a, delivery_id).await,
        DeliveryStatus::Sent
    );
    assert_eq!(
        service_a
            .record_missed_heartbeat(node_b.clone(), HeartbeatPolicy::default())
            .await
            .expect("first missed heartbeat"),
        (PeerStatus::Degraded, 0)
    );
    assert_eq!(
        service_a
            .record_missed_heartbeat(node_b.clone(), HeartbeatPolicy::default())
            .await
            .expect("second missed heartbeat"),
        (PeerStatus::Suspect, 1)
    );
    assert_eq!(
        async_delivery_status(&service_a, delivery_id).await,
        DeliveryStatus::WaitingForPeer
    );
    assert_eq!(service_a.pump_outbound().await.expect("parked"), 0);

    service_b
        .send_heartbeat(node_a.clone(), 7)
        .await
        .expect("send recovery heartbeat");
    let outcomes = service_a
        .process_incoming()
        .await
        .expect("process recovery heartbeat");
    assert!(matches!(
        outcomes.as_slice(),
        [InboundOutcome::HeartbeatReceived {
            status: PeerStatus::Healthy,
            requeued: 1,
            ..
        }]
    ));
    assert_eq!(
        async_delivery_status(&service_a, delivery_id).await,
        DeliveryStatus::Retrying
    );
    assert_eq!(service_a.pump_outbound().await.expect("resend"), 1);

    let outcomes = service_b
        .process_incoming()
        .await
        .expect("receive original and resent events");
    assert_eq!(
        outcomes
            .iter()
            .filter(|outcome| matches!(outcome, InboundOutcome::EventAccepted { .. }))
            .count(),
        1
    );
    assert_eq!(
        outcomes
            .iter()
            .filter(|outcome| matches!(outcome, InboundOutcome::EventDuplicate { .. }))
            .count(),
        1
    );
    service_a.process_incoming().await.expect("process acks");
    assert_eq!(
        async_delivery_status(&service_a, delivery_id).await,
        DeliveryStatus::Delivered
    );
    service_a.shutdown().await;
    let store_b = service_b.shutdown().await;
    assert_eq!(store_b.len(), 1);
}

#[test]
fn trusted_network_routing_skips_offline_peers() {
    let node_a = NodeId::from_legacy_named("node_a").expect("node");
    let node_b = NodeId::from_legacy_named("node_b").expect("node");
    let node_c = NodeId::from_legacy_named("node_c").expect("node");
    let mut registry = PeerRegistry::new();
    registry.register_node(node("node_a"));
    registry.register_node(node("node_b"));
    registry.register_node(node("node_c"));
    for _ in 0..3 {
        registry
            .record_missed_heartbeat(&node_b, HeartbeatPolicy::default())
            .expect("miss heartbeat");
    }
    registry
        .record_heartbeat(&node_c, 1)
        .expect("mark c healthy");
    let mut event = fixture_event("evt_trusted_network", node_a);
    event.routing.scope = RoutingScope::TrustedNetwork;
    let mut store = InMemoryEventStore::new();
    let receipt = store.append(event).expect("append");
    let stored = store
        .replay(ReplayQuery::all().after(EventSequence(receipt.sequence.0 - 1)))
        .expect("replay")
        .pop()
        .expect("stored");

    let mut router = InProcessRouter::new(registry);
    let deliveries = router.route_event(&stored).expect("route");
    let targets: BTreeSet<NodeId> = deliveries
        .into_iter()
        .map(|delivery| delivery.target_node_id)
        .collect();

    assert_eq!(
        targets,
        BTreeSet::from([stored.event.origin_node_id, node_c])
    );
}

#[derive(Clone, Debug, Serialize, Deserialize)]
enum LocalhostKvRequest {
    Apply { command: KvCommand },
    Get { key: String },
    Snapshot,
    InstallSnapshot { snapshot: KvSnapshot },
    Stop,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
enum LocalhostKvResponse {
    Revision { revision: KvRevision },
    Entry { entry: Option<KvEntry> },
    Snapshot { snapshot: KvSnapshot },
    Ok,
    Error { message: String },
}

struct LocalhostKvNode {
    address: String,
    handle: Option<JoinHandle<()>>,
}

impl LocalhostKvNode {
    fn start() -> Self {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("bind localhost kv node");
        let address = listener.local_addr().expect("local addr").to_string();
        let store = Arc::new(Mutex::new(InProcessKvStore::new()));
        let handle_store = Arc::clone(&store);
        let handle = thread::spawn(move || {
            loop {
                let (stream, _address) = listener.accept().expect("accept localhost kv request");
                let mut stream = DaemonControlStream::new(stream);
                let request = read_localhost_kv_request(&mut stream);
                let should_stop = matches!(request, Ok(LocalhostKvRequest::Stop));
                let response = match request {
                    Ok(request) => handle_localhost_kv_request(&handle_store, request),
                    Err(error) => LocalhostKvResponse::Error {
                        message: error.to_string(),
                    },
                };
                write_object_frame_blocking(&mut stream, &response)
                    .expect("write localhost kv response");
                if should_stop {
                    break;
                }
            }
        });

        Self {
            address,
            handle: Some(handle),
        }
    }

    fn address(&self) -> &str {
        &self.address
    }

    fn stop(mut self) {
        let _ = send_localhost_kv_request(self.address(), LocalhostKvRequest::Stop);
        if let Some(handle) = self.handle.take() {
            handle.join().expect("join localhost kv node");
        }
    }
}

fn read_localhost_kv_request(
    stream: &mut DaemonControlStream,
) -> Result<LocalhostKvRequest, NetworkError> {
    read_object_frame_blocking(stream, IROH_DAEMON_COMMAND_MAX_BYTES)
}

fn handle_localhost_kv_request(
    store: &Arc<Mutex<InProcessKvStore>>,
    request: LocalhostKvRequest,
) -> LocalhostKvResponse {
    let mut store = store.lock().expect("lock kv store");
    match request {
        LocalhostKvRequest::Apply { command } => match store.apply_command(command) {
            Ok(revision) => LocalhostKvResponse::Revision { revision },
            Err(error) => LocalhostKvResponse::Error {
                message: error.to_string(),
            },
        },
        LocalhostKvRequest::Get { key } => LocalhostKvResponse::Entry {
            entry: store.get(&key).cloned(),
        },
        LocalhostKvRequest::Snapshot => LocalhostKvResponse::Snapshot {
            snapshot: store.snapshot(),
        },
        LocalhostKvRequest::InstallSnapshot { snapshot } => {
            *store = InProcessKvStore::restore(snapshot);
            LocalhostKvResponse::Ok
        }
        LocalhostKvRequest::Stop => LocalhostKvResponse::Ok,
    }
}

fn send_localhost_kv_request(
    address: &str,
    request: LocalhostKvRequest,
) -> Result<LocalhostKvResponse, String> {
    let stream = std::net::TcpStream::connect(address).map_err(|source| source.to_string())?;
    let mut stream = DaemonControlStream::new(stream);
    stream
        .set_read_timeout(Some(Duration::from_secs(2)))
        .map_err(|source| source.to_string())?;
    stream
        .set_write_timeout(Some(Duration::from_secs(2)))
        .map_err(|source| source.to_string())?;
    write_object_frame_blocking(&mut stream, &request).map_err(|source| source.to_string())?;

    let response: LocalhostKvResponse =
        read_object_frame_blocking(&mut stream, IROH_DAEMON_COMMAND_MAX_BYTES)
            .map_err(|source| source.to_string())?;
    if let LocalhostKvResponse::Error { message } = &response {
        return Err(message.clone());
    }
    Ok(response)
}

fn apply_to_localhost_kv(address: &str, command: KvCommand) -> KvRevision {
    match send_localhost_kv_request(address, LocalhostKvRequest::Apply { command })
        .expect("apply command over localhost")
    {
        LocalhostKvResponse::Revision { revision } => revision,
        response => panic!("unexpected apply response: {response:?}"),
    }
}

fn replicate_to_localhost_kv(addresses: &[String], command: KvCommand) -> Vec<KvRevision> {
    addresses
        .iter()
        .map(|address| apply_to_localhost_kv(address, command.clone()))
        .collect()
}

fn get_localhost_kv_entry(address: &str, key: &str) -> Option<KvEntry> {
    match send_localhost_kv_request(
        address,
        LocalhostKvRequest::Get {
            key: key.to_string(),
        },
    )
    .expect("get entry over localhost")
    {
        LocalhostKvResponse::Entry { entry } => entry,
        response => panic!("unexpected get response: {response:?}"),
    }
}

fn localhost_kv_snapshot(address: &str) -> KvSnapshot {
    match send_localhost_kv_request(address, LocalhostKvRequest::Snapshot)
        .expect("snapshot over localhost")
    {
        LocalhostKvResponse::Snapshot { snapshot } => snapshot,
        response => panic!("unexpected snapshot response: {response:?}"),
    }
}

fn install_localhost_kv_snapshot(address: &str, snapshot: KvSnapshot) {
    match send_localhost_kv_request(address, LocalhostKvRequest::InstallSnapshot { snapshot })
        .expect("install snapshot over localhost")
    {
        LocalhostKvResponse::Ok => {}
        response => panic!("unexpected install snapshot response: {response:?}"),
    }
}

fn wait_for_localhost_kv_entry(address: &str, key: &str, expected: &[u8]) -> KvEntry {
    let deadline = Instant::now() + Duration::from_secs(2);
    loop {
        if let Some(entry) = get_localhost_kv_entry(address, key) {
            if entry.value == expected {
                return entry;
            }
        }
        assert!(
            Instant::now() < deadline,
            "entry {key} did not converge on {address}"
        );
        thread::sleep(Duration::from_millis(20));
    }
}

fn localhost_kv_cluster_member(
    cluster_id: ClusterId,
    node_id: NodeId,
    display_name: &str,
) -> ClusterMemberRecord {
    ClusterMemberRecord::local_voter(
        cluster_id,
        node_id,
        display_name,
        format!("pk_{display_name}"),
        time::OffsetDateTime::now_utc(),
    )
}

fn start_three_localhost_kv_nodes() -> (Vec<LocalhostKvNode>, Vec<String>) {
    let nodes = vec![
        LocalhostKvNode::start(),
        LocalhostKvNode::start(),
        LocalhostKvNode::start(),
    ];
    let addresses = nodes
        .iter()
        .map(|node| node.address().to_string())
        .collect();
    (nodes, addresses)
}

fn stop_localhost_kv_nodes(nodes: Vec<LocalhostKvNode>) {
    for node in nodes {
        node.stop();
    }
}

#[test]
fn localhost_kv_cluster_replicates_membership_and_kv_operations_over_network_object_frames() {
    let (nodes, addresses) = start_three_localhost_kv_nodes();
    let cluster_id = ClusterId::from_legacy_named("cluster_localhost").expect("cluster");
    let node_ids = [
        NodeId::from_legacy_named("node_alpha").expect("node"),
        NodeId::from_legacy_named("node_beta").expect("node"),
        NodeId::from_legacy_named("node_gamma").expect("node"),
    ];

    for (node_id, display_name) in node_ids.iter().zip(["alpha", "beta", "gamma"]) {
        let member = localhost_kv_cluster_member(cluster_id.clone(), node_id.clone(), display_name);
        replicate_to_localhost_kv(
            &addresses,
            cluster_member_put_command(&member).expect("member put command"),
        );
    }
    replicate_to_localhost_kv(
        &addresses,
        KvCommand::Op(KvOp::LeaseGrant {
            lease_id: LeaseId(1),
            ttl_ticks: 10,
        }),
    );
    replicate_to_localhost_kv(
        &addresses,
        KvCommand::Op(KvOp::Put {
            key: "/services/kv/node_alpha".to_string(),
            value: addresses[0].as_bytes().to_vec(),
            lease_id: Some(LeaseId(1)),
        }),
    );
    let revisions = replicate_to_localhost_kv(
        &addresses,
        KvCommand::Txn(KvTxn {
            compares: vec![KvCompare::Missing {
                key: "/config/epoch".to_string(),
            }],
            success: vec![KvOp::Put {
                key: "/config/epoch".to_string(),
                value: b"1".to_vec(),
                lease_id: None,
            }],
            failure: vec![],
        }),
    );

    assert_eq!(revisions, vec![KvRevision(5), KvRevision(5), KvRevision(5)]);
    for address in &addresses {
        for node_id in &node_ids {
            assert!(
                get_localhost_kv_entry(address, &cluster_member_key(node_id)).is_some(),
                "missing member {node_id} on {address}"
            );
        }
        assert_eq!(
            get_localhost_kv_entry(address, "/config/epoch")
                .expect("epoch")
                .value,
            b"1"
        );
        assert_eq!(
            get_localhost_kv_entry(address, "/services/kv/node_alpha")
                .expect("service")
                .lease_id,
            Some(LeaseId(1))
        );
    }

    stop_localhost_kv_nodes(nodes);
}

#[test]
fn localhost_kv_cluster_catches_up_delayed_node_from_snapshot_over_network_object_frames() {
    let (nodes, addresses) = start_three_localhost_kv_nodes();
    let first_two = addresses[..2].to_vec();

    replicate_to_localhost_kv(
        &first_two,
        KvCommand::Op(KvOp::Put {
            key: "/config/a".to_string(),
            value: b"one".to_vec(),
            lease_id: None,
        }),
    );
    replicate_to_localhost_kv(
        &first_two,
        KvCommand::Op(KvOp::Put {
            key: "/config/b".to_string(),
            value: b"two".to_vec(),
            lease_id: None,
        }),
    );

    assert!(get_localhost_kv_entry(&addresses[2], "/config/b").is_none());
    install_localhost_kv_snapshot(&addresses[2], localhost_kv_snapshot(&addresses[0]));
    wait_for_localhost_kv_entry(&addresses[2], "/config/b", b"two");

    replicate_to_localhost_kv(
        &addresses,
        KvCommand::Op(KvOp::Put {
            key: "/config/c".to_string(),
            value: b"three".to_vec(),
            lease_id: None,
        }),
    );

    let snapshots: Vec<KvSnapshot> = addresses
        .iter()
        .map(|address| localhost_kv_snapshot(address))
        .collect();
    assert!(
        snapshots
            .iter()
            .all(|snapshot| snapshot.revision == KvRevision(3))
    );
    for address in &addresses {
        assert_eq!(
            wait_for_localhost_kv_entry(address, "/config/a", b"one").value,
            b"one"
        );
        assert_eq!(
            wait_for_localhost_kv_entry(address, "/config/b", b"two").value,
            b"two"
        );
        assert_eq!(
            wait_for_localhost_kv_entry(address, "/config/c", b"three").value,
            b"three"
        );
    }

    stop_localhost_kv_nodes(nodes);
}

#[derive(Default)]
struct CountingIoObserver {
    actual: std::sync::atomic::AtomicU64,
    skipped: std::sync::atomic::AtomicU64,
    disk_read_bytes: std::sync::atomic::AtomicU64,
    disk_write_bytes: std::sync::atomic::AtomicU64,
}

impl IoObserver for CountingIoObserver {
    fn on_disk_read(&self, bytes: u64) {
        self.disk_read_bytes
            .fetch_add(bytes, std::sync::atomic::Ordering::Relaxed);
    }
    fn on_disk_write(&self, bytes: u64) {
        self.disk_write_bytes
            .fetch_add(bytes, std::sync::atomic::Ordering::Relaxed);
    }
    fn on_object_file_actual_write(&self) {
        self.actual
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }
    fn on_object_file_skipped_write(&self) {
        self.skipped
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    }
}

static IO_OBSERVER_TEST_MUTEX: std::sync::Mutex<()> = std::sync::Mutex::new(());

#[test]
fn cluster_kv_watch_events_cache_reuses_unchanged_event_view() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-watch-event-cache");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("paths");
    let first = KvEvent {
        revision: KvRevision(1),
        key: "/watch/cache/first".to_string(),
        kind: KvEventKind::Put {
            value: b"first".to_vec(),
        },
    };
    let second = KvEvent {
        revision: KvRevision(2),
        key: "/watch/cache/second".to_string(),
        kind: KvEventKind::Put {
            value: b"second".to_vec(),
        },
    };
    let record = SinomoObjectCodec::default()
        .encode(&first)
        .expect("encode watch event");
    let mut log = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&paths.kv_watch_events_log)
        .expect("open watch event log");
    log.write_all(&(record.len() as u32).to_be_bytes())
        .expect("write record length");
    log.write_all(&record).expect("write record");
    log.sync_data().expect("sync watch event log");
    drop(log);

    assert!(
        cached_cluster_kv_watch_events_for_test(&paths).is_none(),
        "cold watch-event reads should start without a cache entry"
    );

    assert_eq!(
        cluster_kv_watch_events(&paths).expect("first read"),
        vec![first.clone()]
    );
    assert_eq!(
        cached_cluster_kv_watch_events_for_test(&paths),
        Some(vec![first.clone()]),
        "first read should cache the compacted watch-event view"
    );

    assert_eq!(
        cluster_kv_watch_events(&paths).expect("cached read"),
        vec![first.clone()]
    );

    append_cluster_kv_watch_events(&paths, std::slice::from_ref(&second))
        .expect("append second event");
    assert_eq!(
        cached_cluster_kv_watch_events_for_test(&paths),
        Some(vec![first.clone(), second.clone()]),
        "append should refresh the cache for the next drain"
    );
    assert_eq!(
        cluster_kv_watch_events(&paths).expect("cached read after append"),
        vec![first, second]
    );
}

#[test]
fn cluster_kv_watch_caches_retain_recent_entries_at_capacity() {
    let _guard = CLUSTER_KV_WATCH_CACHE_TEST_MUTEX
        .lock()
        .expect("watch cache mutex");
    let root = sinomo_testdir::TestDir::new("sinomo-network-watch-cache-lru");

    let hot_event_paths = ClusterPaths::new(&SinomoDataDir::new(root.join("000-hot-events")));
    for index in 0..cluster_kv_watch_event_cache_capacity_for_test().saturating_sub(1) {
        let quiet_paths = ClusterPaths::new(&SinomoDataDir::new(
            root.join(format!("100-event-{index:04}")),
        ));
        record_cluster_kv_watch_event_cache_for_test(&quiet_paths);
    }
    record_cluster_kv_watch_event_cache_for_test(&hot_event_paths);
    assert!(
        refresh_cluster_kv_watch_event_cache_for_test(&hot_event_paths),
        "looking up the hot watch-event cache entry should refresh its recency"
    );
    let extra_event_paths = ClusterPaths::new(&SinomoDataDir::new(root.join("999-extra-events")));
    record_cluster_kv_watch_event_cache_for_test(&extra_event_paths);
    assert!(
        cluster_kv_watch_event_cache_contains_for_test(&hot_event_paths),
        "recent watch-event cache entry should survive capacity churn"
    );

    let hot_registration_path = root.join("000-hot-registration.sobj");
    for index in 0..cluster_kv_watch_registration_cache_capacity_for_test().saturating_sub(1) {
        record_cluster_kv_watch_registration_cache_for_test(
            &root.join(format!("100-registration-{index:04}.sobj")),
        );
    }
    record_cluster_kv_watch_registration_cache_for_test(&hot_registration_path);
    assert!(
        refresh_cluster_kv_watch_registration_cache_for_test(&hot_registration_path),
        "looking up the hot watch-registration cache entry should refresh its recency"
    );
    record_cluster_kv_watch_registration_cache_for_test(&root.join("999-extra-registration.sobj"));
    assert!(
        cluster_kv_watch_registration_cache_contains_for_test(&hot_registration_path),
        "recent watch-registration cache entry should survive capacity churn"
    );

    remove_cluster_kv_watch_event_cache_entries_under_root_for_test(&root);
    remove_cluster_kv_watch_registration_cache_entries_under_root_for_test(&root);
}

#[test]
fn write_cluster_state_observer_counts_actual_then_skipped() {
    // Serialize with any other test that swaps the global I/O observer.
    let _guard = IO_OBSERVER_TEST_MUTEX.lock().expect("test mutex");

    let observer = Arc::new(CountingIoObserver::default());
    let previous: Option<Arc<dyn IoObserver>> =
        set_io_observer(Some(observer.clone() as Arc<dyn IoObserver>));

    let root = sinomo_testdir::TestDir::new("sinomo-network-storage-observer");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("paths");

    let cluster_id = ClusterId::from_legacy_named("cluster_storage_observer").expect("cluster id");
    let node = NodeId::from_legacy_named("node_storage_observer").expect("node id");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "storage observer test",
        node,
        "node",
        "pk",
        OffsetDateTime::now_utc(),
    );

    write_cluster_state(&paths, &state).expect("first write");
    write_cluster_state(&paths, &state).expect("second write should short-circuit");

    let actual = observer.actual.load(std::sync::atomic::Ordering::Relaxed);
    let skipped = observer.skipped.load(std::sync::atomic::Ordering::Relaxed);
    let write_bytes = observer
        .disk_write_bytes
        .load(std::sync::atomic::Ordering::Relaxed);
    // `IO_OBSERVER` is process-wide, so a concurrently-running test that writes an
    // object file is counted here too. Our two writes contribute exactly one
    // actual write (first) and one skipped write (second, identical content, to a
    // unique temp dir no other test touches), so assert lower bounds. The precise
    // "identical re-write is skipped" behavior is covered race-free by
    // `write_object_file_skips_identical_and_rewrites_after_external_change`.
    assert!(
        actual >= 1,
        "expected at least our one actual write, got {actual}"
    );
    assert!(
        skipped >= 1,
        "expected at least our one skipped write, got {skipped}"
    );
    assert!(write_bytes > 0, "actual write should report disk bytes");

    // Restore the previous observer so we don't poison sibling tests.
    let _ = set_io_observer(previous);
}

#[test]
fn write_object_file_skips_compare_read_when_length_differs() {
    let _guard = IO_OBSERVER_TEST_MUTEX.lock().expect("test mutex");

    let observer = Arc::new(CountingIoObserver::default());
    let previous: Option<Arc<dyn IoObserver>> =
        set_io_observer(Some(observer.clone() as Arc<dyn IoObserver>));

    let root = sinomo_testdir::TestDir::new("sinomo-network-sparse-objfile-rewrite");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("paths");
    std::fs::OpenOptions::new()
        .create(true)
        .write(true)
        .truncate(true)
        .open(&paths.state)
        .expect("open sparse state")
        .set_len(MAX_OBJECT_FILE_READ_BYTES + 1)
        .expect("make sparse oversized state");

    let cluster_id = ClusterId::from_legacy_named("cluster_sparse_rewrite").expect("cluster id");
    let node = NodeId::from_legacy_named("node_sparse_rewrite").expect("node id");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "sparse rewrite test",
        node,
        "node",
        "pk",
        OffsetDateTime::now_utc(),
    );

    write_cluster_state(&paths, &state).expect("rewrite sparse state");

    let read_bytes = observer
        .disk_read_bytes
        .load(std::sync::atomic::Ordering::Relaxed);
    assert!(
        read_bytes < MAX_OBJECT_FILE_READ_BYTES,
        "length-mismatched object files should not be read back before rewrite; observed {read_bytes} bytes"
    );

    let _ = set_io_observer(previous);
}

#[test]
fn read_optional_object_file_treats_only_missing_file_as_absent() {
    #[derive(Debug, Eq, PartialEq, serde::Serialize, serde::Deserialize)]
    struct OptionalObjectFixture {
        value: u64,
    }

    let root = sinomo_testdir::TestDir::new("sinomo-network-optional-object-read");
    std::fs::create_dir_all(&root).expect("root");

    let missing = root.join("missing.sobj");
    assert_eq!(
        crate::storage::read_optional_object_file::<OptionalObjectFixture>(&missing)
            .expect("missing optional object"),
        None,
        "a missing optional object should be absent without a pre-open exists probe"
    );

    let object = root.join("present.sobj");
    crate::storage::write_object_file(&object, &OptionalObjectFixture { value: 42 })
        .expect("write object");
    assert_eq!(
        crate::storage::read_optional_object_file::<OptionalObjectFixture>(&object)
            .expect("present optional object"),
        Some(OptionalObjectFixture { value: 42 })
    );

    let directory = root.join("directory.sobj");
    std::fs::create_dir_all(&directory).expect("directory");
    assert!(
        crate::storage::read_optional_object_file::<OptionalObjectFixture>(&directory).is_err(),
        "a directory at an optional object path is a storage error, not absence"
    );
}

#[test]
fn write_object_file_create_new_falls_back_when_hard_links_are_unsupported() {
    #[derive(Debug, Eq, PartialEq, serde::Serialize, serde::Deserialize)]
    struct CreateNewFixture {
        value: u64,
    }

    let root = sinomo_testdir::TestDir::new("sinomo-network-create-new-link-fallback");
    std::fs::create_dir_all(&root).expect("root");
    let path = root.join("object.sobj");

    crate::storage::force_write_object_file_create_new_unsupported_link_for_test(&path);
    assert!(
        crate::storage::write_object_file_create_new_serialized(
            &path,
            &CreateNewFixture { value: 42 },
        )
        .expect("fallback create-new write"),
        "missing target should be created when hard links are unsupported"
    );
    assert_eq!(
        crate::storage::read_object_file::<CreateNewFixture>(&path).expect("read created object"),
        CreateNewFixture { value: 42 }
    );
    assert!(
        !crate::storage::write_object_file_create_new_serialized(
            &path,
            &CreateNewFixture { value: 7 },
        )
        .expect("fallback existing target"),
        "existing target should not be replaced in the hard-link fallback"
    );
    assert_eq!(
        crate::storage::read_object_file::<CreateNewFixture>(&path).expect("read original object"),
        CreateNewFixture { value: 42 }
    );
    assert!(
        std::fs::read_dir(&root)
            .expect("root entries")
            .filter_map(Result::ok)
            .filter_map(|entry| entry.file_name().to_str().map(str::to_string))
            .all(|name| !name.contains(".create-new-tmp-")),
        "create-new fallback should not leave staged temp files behind"
    );
    crate::storage::clear_write_object_file_create_new_unsupported_link_for_test(&path);
}

#[test]
fn write_object_file_skips_identical_and_rewrites_after_external_change() {
    let _guard = OBJECT_FILE_WRITE_MARK_CACHE_TEST_MUTEX
        .lock()
        .expect("object mark cache mutex");
    // Unique path so this test is independent of the process-wide I/O observer.
    let root = sinomo_testdir::TestDir::new("sinomo-network-objfile-guard");
    std::fs::create_dir_all(&root).expect("root");
    let path = root.join("obj.sobj");

    let value = "alpha".to_string();
    crate::storage::write_object_file(&path, &value).expect("initial write");
    let mtime_after_write = std::fs::metadata(&path)
        .expect("metadata")
        .modified()
        .expect("mtime");

    // An identical re-write takes the fast path and leaves the file untouched.
    crate::storage::write_object_file(&path, &value).expect("identical re-write");
    assert_eq!(
        std::fs::metadata(&path)
            .expect("metadata")
            .modified()
            .expect("mtime"),
        mtime_after_write,
        "an identical re-write must be skipped without rewriting the file"
    );

    // Another writer replaces the content behind our back with the same byte
    // length. This must be detected by the file-identity guard, not just length.
    let original_len = std::fs::metadata(&path).expect("metadata").len() as usize;
    let replacement = vec![b'x'; original_len];
    let replacement_path = root.join("replacement.sobj");
    std::fs::write(&replacement_path, replacement).expect("external write");
    std::fs::rename(&replacement_path, &path).expect("external replace");

    // Writing our content again must detect the change via the stat guard, fall
    // back to read + compare, and actually rewrite -- never falsely skip.
    crate::storage::write_object_file(&path, &value).expect("rewrite after external change");
    let restored: String = SinomoObjectCodec::default()
        .decode(&std::fs::read(&path).expect("read"))
        .expect("decode");
    assert_eq!(
        restored, value,
        "a file changed since our last write must be rewritten, not skipped"
    );
}

#[test]
fn object_file_write_mark_cache_retains_recent_entry_at_capacity() {
    let _guard = OBJECT_FILE_WRITE_MARK_CACHE_TEST_MUTEX
        .lock()
        .expect("object mark cache mutex");
    let root = sinomo_testdir::TestDir::new("sinomo-network-object-mark-lru");
    let hot_path = root.join("000-hot.sobj");
    for index in 0..object_file_write_mark_cache_capacity_for_test().saturating_sub(1) {
        record_object_file_write_mark_for_test(&root.join(format!("100-quiet-{index:04}.sobj")));
    }
    record_object_file_write_mark_for_test(&hot_path);
    assert!(
        refresh_object_file_write_mark_for_test(&hot_path),
        "looking up the hot object write mark should refresh its recency"
    );

    record_object_file_write_mark_for_test(&root.join("999-extra.sobj"));

    assert!(
        object_file_write_mark_cache_contains_for_test(&hot_path),
        "recent object write mark should survive capacity churn"
    );
    remove_object_file_write_mark_entries_under_root_for_test(&root);
}

#[test]
fn write_object_file_cleans_temp_file_after_replace_failure() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-objfile-temp-cleanup");
    std::fs::create_dir_all(&root).expect("root");
    let path = root.join("obj.sobj");
    std::fs::create_dir(&path).expect("target directory");

    let error = crate::storage::write_object_file(&path, &"alpha".to_string())
        .expect_err("replacing a directory should fail");
    assert!(
        error.to_string().contains("obj.sobj"),
        "unexpected error: {error}"
    );
    let leftovers = std::fs::read_dir(&root)
        .expect("read temp dir")
        .filter_map(|entry| entry.ok())
        .filter(|entry| {
            entry
                .file_name()
                .to_str()
                .is_some_and(|name| name.starts_with(".obj.sobj.tmp-"))
        })
        .count();
    assert_eq!(
        leftovers, 0,
        "failed object replacement should not leave staged temp files"
    );
}

#[test]
fn member_publish_already_current_hands_back_snapshot_to_stale_publisher() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-member-publish-stale-snapshot");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_member_publish_stale_snapshot").expect("cluster");
    let local = NodeId::from_legacy_named("node_member_publish_stale_snapshot").expect("local");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "member publish stale snapshot",
        local.clone(),
        "local",
        "pk-local",
        now,
    );
    state.members[0].capabilities = sinomo_node::main_daemon_capabilities(&state.members[0].role);
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state to kv");

    let mut published = state.members[0].clone();
    published.endpoints = vec![daemon_lan_endpoint(
        &local,
        "10.49.0.7:21353".to_string(),
        10,
    )];

    // First publish commits the endpoint records.
    let mut host = RecordingClusterMemberPublishHost::default();
    let committed = handle_cluster_member_publish_request_with_host(
        &paths,
        ClusterMemberPublishRequest {
            members: vec![published.clone()],
            local_kv_revision: None,
        },
        local.as_str(),
        &mut host,
    )
    .expect("first member publish");
    assert!(committed.accepted);
    assert_eq!(host.commits, 1);
    let current_revision = read_cluster_kv_current_snapshot(&paths)
        .expect("snapshot after commit")
        .revision;

    // Re-publishing identical records is a no-op commit-wise, but the response
    // must hand the current snapshot back to publishers that are behind (or
    // report no revision at all) — this is how learner KV snapshots converge.
    for (publisher_revision, expects_snapshot) in [
        (Some(current_revision), false),
        // Lag-only invariant: a publisher AHEAD of the responder means the
        // responder is the stale one; it must never ship its snapshot
        // backwards.
        (Some(KvRevision(current_revision.0 + 1)), false),
        (Some(KvRevision(0)), true),
        (None, true),
    ] {
        let mut repeat_host = RecordingClusterMemberPublishHost::default();
        let response = handle_cluster_member_publish_request_with_host(
            &paths,
            ClusterMemberPublishRequest {
                members: vec![published.clone()],
                local_kv_revision: publisher_revision,
            },
            local.as_str(),
            &mut repeat_host,
        )
        .expect("repeat member publish");
        assert!(response.accepted);
        assert_eq!(response.detail, "member endpoints already current");
        assert_eq!(repeat_host.commits, 0, "no-op publish must not commit");
        assert_eq!(
            response.kv_snapshot.is_some(),
            expects_snapshot,
            "publisher revision {publisher_revision:?} should{} receive a snapshot",
            if expects_snapshot { "" } else { " not" }
        );
        if let Some(snapshot) = response.kv_snapshot {
            assert_eq!(snapshot.revision, current_revision);
        }
    }
}

#[test]
fn local_member_publish_forced_sync_publishes_even_when_records_current() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-local-member-publish-forced-sync");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_local_member_publish_forced_sync").expect("cluster");
    let local = NodeId::from_legacy_named("node_local_member_publish_forced_sync").expect("local");
    let voter =
        NodeId::from_legacy_named("node_local_member_publish_forced_sync_voter").expect("voter");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "local member publish forced sync",
        local.clone(),
        "local",
        "pk-local",
        now,
    );
    state.members[0].capabilities = sinomo_node::main_daemon_capabilities(&state.members[0].role);
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();
    let mut remote = ClusterMemberRecord::local_voter(
        cluster_id,
        voter.clone(),
        "remote voter",
        "pk-voter",
        now,
    );
    remote.capabilities = sinomo_node::main_daemon_capabilities(&remote.role);
    remote.allowed_capabilities = remote.capabilities.clone();
    remote.endpoints = vec![daemon_lan_endpoint(
        &voter,
        "10.49.1.7:21353".to_string(),
        10,
    )];
    state.members.push(remote);
    write_cluster_state(&paths, &state).expect("write state");

    // Seed the local snapshot so the local member records already match —
    // the historical short-circuit that froze learner snapshots forever.
    let mut seeded = InProcessKvStore::new();
    for member in cluster_local_process_members(&state) {
        let txn = KvTxn {
            compares: Vec::new(),
            success: vec![
                KvOp::put_serde(cluster_member_key(&member.node_id), &member, None)
                    .expect("member op"),
            ],
            failure: Vec::new(),
        };
        seeded.txn(txn).expect("seed member");
    }
    write_cluster_kv_snapshot(&paths, &seeded.snapshot()).expect("seed snapshot");
    assert!(
        cluster_member_publish_matches_kv(&paths, &cluster_local_process_members(&state))
            .expect("matches kv"),
        "fixture must reproduce the already-published state"
    );

    let mut imported_store = seeded;
    imported_store
        .put("/kv/forced-sync/imported", b"ok".to_vec(), None)
        .expect("imported marker");

    // Without the force flag the publish short-circuits: no RPC, no import.
    let mut idle_host = RecordingClusterLocalMemberPublishHost {
        has_quorum: false,
        response: Some(ClusterMemberPublishResponse {
            accepted: true,
            detail: "published".to_string(),
            state: state.clone(),
            kv_snapshot: Some(imported_store.snapshot()),
        }),
        ..Default::default()
    };
    publish_local_members_via_voter_with_host(
        &paths,
        &state,
        ClusterLocalMemberPublishOptions {
            member_publish_timeout: Duration::from_secs(5),
            force_kv_snapshot_sync: false,
        },
        &mut idle_host,
    )
    .expect("non-forced publish");
    assert!(idle_host.sends.is_empty());

    // With the force flag the learner publishes anyway, reports its local
    // revision, and imports the newer snapshot the voter hands back.
    let mut forced_host = RecordingClusterLocalMemberPublishHost {
        has_quorum: false,
        response: Some(ClusterMemberPublishResponse {
            accepted: true,
            detail: "published".to_string(),
            state: state.clone(),
            kv_snapshot: Some(imported_store.snapshot()),
        }),
        ..Default::default()
    };
    publish_local_members_via_voter_with_host(
        &paths,
        &state,
        ClusterLocalMemberPublishOptions {
            member_publish_timeout: Duration::from_secs(5),
            force_kv_snapshot_sync: true,
        },
        &mut forced_host,
    )
    .expect("forced publish");
    assert_eq!(forced_host.sends.len(), 1);
    assert!(
        read_cluster_kv_current_snapshot(&paths)
            .expect("snapshot after forced sync")
            .get("/kv/forced-sync/imported")
            .is_some(),
        "forced sync must import the voter's newer snapshot"
    );

    // A stale responder (e.g. a lagging bridge) answering with an OLDER
    // snapshot must never roll the local KV back.
    let local_revision_before = read_cluster_kv_current_snapshot(&paths)
        .expect("snapshot before stale response")
        .revision;
    let mut stale_store = InProcessKvStore::new();
    stale_store
        .put("/kv/forced-sync/stale-marker", b"old".to_vec(), None)
        .expect("stale marker");
    let stale_snapshot = stale_store.snapshot();
    assert!(stale_snapshot.revision < local_revision_before);
    let mut stale_host = RecordingClusterLocalMemberPublishHost {
        has_quorum: false,
        response: Some(ClusterMemberPublishResponse {
            accepted: true,
            detail: "published".to_string(),
            state: state.clone(),
            kv_snapshot: Some(stale_snapshot),
        }),
        ..Default::default()
    };
    publish_local_members_via_voter_with_host(
        &paths,
        &state,
        ClusterLocalMemberPublishOptions {
            member_publish_timeout: Duration::from_secs(5),
            force_kv_snapshot_sync: true,
        },
        &mut stale_host,
    )
    .expect("forced publish against stale responder");
    let after = read_cluster_kv_current_snapshot(&paths).expect("snapshot after stale response");
    assert_eq!(after.revision, local_revision_before);
    assert!(
        after.get("/kv/forced-sync/stale-marker").is_none(),
        "an older responder snapshot must not be imported"
    );
}

#[derive(Default)]
struct NodeOnlySnapshotRefreshHost {
    node_snapshot: Option<KvSnapshot>,
    direct_fetches: usize,
    node_calls: usize,
}

impl ClusterKvSnapshotRefreshHost for NodeOnlySnapshotRefreshHost {
    fn known_raft_leader_id(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
    ) -> Result<Option<NodeId>, NetworkError> {
        Ok(None)
    }

    fn fetch_cluster_kv_snapshot(
        &mut self,
        endpoint: &ClusterEndpointRecord,
        _timeout: Duration,
    ) -> Result<KvSnapshot, NetworkError> {
        self.direct_fetches += 1;
        Err(NetworkError::Io {
            operation: "test direct snapshot fetch".to_string(),
            detail: format!("{} is unreachable in this test", endpoint.address),
        })
    }

    fn restore_cluster_raft_from_snapshot_if_newer(
        &mut self,
        _paths: &ClusterPaths,
        _local_node_id: &NodeId,
        _snapshot: KvSnapshot,
    ) -> Result<bool, NetworkError> {
        Ok(false)
    }

    fn send_object_rpc_to_node(
        &mut self,
        _state: &ClusterBootstrapState,
        target_node_id: &NodeId,
        request: &ObjectRpcRequest,
        _timeout: Duration,
    ) -> Result<ObjectRpcResponse, NetworkError> {
        self.node_calls += 1;
        assert!(!target_node_id.as_str().is_empty());
        assert_eq!(request.route, sinomo_kv::CLUSTER_KV_SNAPSHOT_ROUTE);
        let payload = sinomo_kv::cluster_kv_snapshot_response_rpc_payload(
            self.node_snapshot.as_ref().expect("node snapshot"),
        )?;
        Ok(ObjectRpcResponse::from_encoded_body(
            payload.route,
            payload.body,
        ))
    }
}

#[test]
fn refresh_current_cluster_kv_store_falls_back_to_node_snapshot_fetch() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-refresh-node-fallback");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_refresh_relay_fallback").expect("cluster");
    let local = NodeId::from_legacy_named("node_refresh_relay_fallback").expect("local");
    let voter = NodeId::from_legacy_named("node_refresh_relay_fallback_voter").expect("voter");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "refresh relay fallback",
        local.clone(),
        "local",
        "pk-local",
        now,
    );
    state.members[0].capabilities = sinomo_node::main_daemon_capabilities(&state.members[0].role);
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();
    let mut remote = ClusterMemberRecord::local_voter(
        cluster_id,
        voter.clone(),
        "remote voter",
        "pk-voter",
        now,
    );
    remote.capabilities = sinomo_node::main_daemon_capabilities(&remote.role);
    remote.allowed_capabilities = remote.capabilities.clone();
    remote.endpoints = vec![daemon_lan_endpoint(
        &voter,
        "10.49.2.7:21353".to_string(),
        10,
    )];
    state.members.push(remote);
    write_cluster_state(&paths, &state).expect("write state");
    write_cluster_kv_snapshot(&paths, &InProcessKvStore::new().snapshot()).expect("empty snapshot");

    let mut node_store = InProcessKvStore::new();
    node_store
        .put("/kv/relay/imported", b"ok".to_vec(), None)
        .expect("relayed marker");
    let mut host = NodeOnlySnapshotRefreshHost {
        node_snapshot: Some(node_store.snapshot()),
        ..Default::default()
    };

    let store = refresh_current_cluster_kv_store_with_host(
        &paths,
        &state,
        ClusterControlPlaneTimeouts::default_daemon_transport().kv_snapshot_refresh_options(),
        &mut host,
    )
    .expect("refresh with relay fallback");

    assert!(host.direct_fetches > 0, "direct fetch must be attempted");
    assert_eq!(host.node_calls, 1, "node fallback must run exactly once");
    assert!(store.snapshot().get("/kv/relay/imported").is_some());
    assert!(
        read_cluster_kv_current_snapshot(&paths)
            .expect("imported snapshot")
            .get("/kv/relay/imported")
            .is_some(),
        "relayed snapshot must be written locally"
    );
}
